//! Per-node config editors and the single-node kind picker.
//!
//! One editor function per [`NodeKind`] inner config, generated by the
//! `impl_node_editor!` declarative macro (a trimmed cousin of texture's
//! `impl_config_editor!`).  Every editor has the shape:
//!
//! ```text
//! pub fn xxx_editor(ui: &mut egui::Ui, cfg: &mut XxxConfig) -> EditorResponse
//! ```
//!
//! and renders only its fields — *no* surrounding collapsing header — so the
//! same function works inside a canvas node box, an inspector panel, or a
//! plain window.  [`node_kind_editor`] wraps a kind picker around the right
//! body for editing a whole [`NodeKind`] in one call.
//!
//! Slider ranges are lifted from each config's `impl_genotype!` invocation so
//! the editor bounds match the evolutionary search bounds (frequencies and
//! rates use logarithmic sliders to match their `f32_log` mutation kind).

use bevy_egui::egui;

use crate::adsr::{AdsrCurve, AdsrEnvelope};
use crate::chorus::Chorus;
use crate::filter::{BiquadBandpass, BiquadHighpass, BiquadLowpass};
use crate::gate::Gate;
use crate::lfo::{Lfo, LfoShape};
use crate::mix::{Gain, Mix};
use crate::node::NodeKind;
use crate::noise::{BrownNoise, PinkNoise, WhiteNoise};
use crate::oscillator::{AntiAlias, SawPolarity, SawtoothOsc, SineOsc, SquareOsc, TriangleOsc};
use crate::reverb::Reverb;

use super::{EditorResponse, bool_instant, drag_value_debounced, ranged_slider};

// ---------------------------------------------------------------------------
// Editor-generating macro
// ---------------------------------------------------------------------------

/// One config's parameter widgets, reachable from the config *type*.
///
/// Every node config implements this, generated alongside its `*_editor`
/// function by `impl_node_editor!` below. It exists so `node_kind_body` can
/// be generated from `symbios_audio::for_each_node_kind!`: the roster names
/// each variant's config type, not the name of the function that edits it,
/// so a type-dispatched call is the only handle it can offer. Private —
/// callers use the `*_editor` functions or `node_kind_body`.
trait NodeConfigEditor {
    fn edit(&mut self, ui: &mut egui::Ui) -> EditorResponse;
}

/// Generate a per-node editor function from a concise field description.
///
/// The fields become the rows of a two-column grid — the name on the left,
/// the control on the right, the unit written into the value ("500 Hz",
/// "0.40 s") — so every name in a node box starts at the same edge (#59,
/// Overlands #1332). `Slider::text` used to put the name *after* the value,
/// which set each name's position by how wide its value happened to be and
/// ran the long ones up against the box's border.
///
/// Widget kinds:
///
/// | Kind | Widget |
/// |------|--------|
/// | `slider(label, unit, field, range)` | linear `f32` slider |
/// | `slider_log(label, unit, field, range)` | logarithmic `f32` slider (freq/rate) |
/// | `drag(label, unit, field, speed, range)` | `f32` drag value, clamped to range |
/// | `bool(label, field)` | checkbox |
/// | `enum_select(label, field, [(Btn, Variant), …])` | selectable-row picker |
///
/// A trailing `note "…"` writes one weak line under the grid — for what a
/// node does that its parameters do not show (a [`Gate`]'s window).
macro_rules! impl_node_editor {
    (
        $(#[doc = $doc:expr])*
        fn $fn_name:ident, $Config:ty =>
        { $( $w:ident $args:tt ),* $(,)? }
        $( note $note:expr )?
    ) => {
        $(#[doc = $doc])*
        pub fn $fn_name(ui: &mut egui::Ui, cfg: &mut $Config) -> EditorResponse {
            #[allow(unused_mut)]
            let mut res = EditorResponse::NONE;
            egui::Grid::new(concat!(stringify!($fn_name), "_rows"))
                .num_columns(2)
                .show(ui, |ui| {
                    $( impl_node_editor!(@w ui, cfg, res, $w $args); )*
                });
            $( ui.label(egui::RichText::new($note).weak()); )?
            res
        }

        impl NodeConfigEditor for $Config {
            fn edit(&mut self, ui: &mut egui::Ui) -> EditorResponse {
                $fn_name(ui, self)
            }
        }
    };

    // f32 linear slider.
    (@w $ui:ident, $cfg:ident, $res:ident,
     slider ($label:expr, $unit:expr, $field:ident, $range:expr)) => {
        $ui.label($label);
        $res.merge(ranged_slider($ui, &mut $cfg.$field, $range, |s| s.suffix($unit)));
        $ui.end_row();
    };
    // f32 logarithmic slider — for frequencies / rates (matches `f32_log`).
    (@w $ui:ident, $cfg:ident, $res:ident,
     slider_log ($label:expr, $unit:expr, $field:ident, $range:expr)) => {
        $ui.label($label);
        $res.merge(ranged_slider($ui, &mut $cfg.$field, $range, |s| {
            s.logarithmic(true).suffix($unit)
        }));
        $ui.end_row();
    };
    // f32 drag value (wide-range amounts), clamped to `range`.
    (@w $ui:ident, $cfg:ident, $res:ident,
     drag ($label:expr, $unit:expr, $field:ident, $speed:expr, $range:expr)) => {
        $ui.label($label);
        $res.merge(drag_value_debounced(
            $ui,
            &mut $cfg.$field,
            $speed,
            $range,
            $unit,
        ));
        $ui.end_row();
    };
    // bool checkbox — the name is the grid's left cell, so the box itself
    // carries no label of its own.
    (@w $ui:ident, $cfg:ident, $res:ident, bool ($label:expr, $field:ident)) => {
        $ui.label($label);
        $res.merge(bool_instant($ui, &mut $cfg.$field, ""));
        $ui.end_row();
    };
    // enum selectable-row picker.  Variants must be `Copy + PartialEq`.
    (@w $ui:ident, $cfg:ident, $res:ident,
     enum_select ($label:expr, $field:ident, [ $(($btn:expr, $variant:expr)),+ $(,)? ])) => {
        $ui.label($label);
        $ui.horizontal(|ui| {
            $(
                let selected = $cfg.$field == $variant;
                if ui.selectable_label(selected, $btn).clicked() && !selected {
                    $cfg.$field = $variant;
                    $res.changed = true;
                    $res.rebake = true;
                }
            )+
        });
        $ui.end_row();
    };
}

