// ---------------------------------------------------------------------------
// NodeKind-level editor (kind picker + body)
// ---------------------------------------------------------------------------

/// The picker, the labels and the per-kind body, all generated from
/// `symbios_audio::for_each_node_kind!`.
///
/// These three used to be hand-written lists, and the roster they encoded was
/// the *fourth* copy of the node vocabulary in the family — after
/// `symbios-audio`'s own enum and Overlands' two mirror rosters. `NodeKind` is
/// `#[non_exhaustive]`, so nothing here could ever be checked against it: a
/// kind added upstream simply never appeared in the dropdown, and the tests
/// below passed because they compared these lists against each other.
/// Generating them means a kind added upstream arrives in the picker, with a
/// default and an editor body, on the version bump alone.
macro_rules! define_kind_picker {
    (
        unit: { $(($uv:ident, $ul:literal)),* $(,)? }
        data: { $(($dv:ident, $dt:ty, $dl:literal)),* $(,)? }
    ) => {
        /// Node kinds in display order for the picker dropdown — upstream's
        /// roster order.
        pub(crate) const KIND_LABELS: &[&str] = &[ $( $ul, )* $( $dl, )* ];

        /// Build a default node of the kind named by `label` (the inverse of
        /// [`node_kind_label`]).  Unknown labels fall back to
        /// [`NodeKind::Silence`].
        pub(crate) fn default_kind_for(label: &str) -> NodeKind {
            match label {
                $( $ul => NodeKind::$uv, )*
                $( $dl => NodeKind::$dv(<$dt>::default()), )*
                _ => NodeKind::Silence,
            }
        }

        /// Render only the parameter widgets for `kind` — no kind picker, no
        /// header.
        ///
        /// Use this when the surrounding UI already conveys the node's type
        /// (e.g. a canvas node box that paints the kind name in its title
        /// bar).
        pub fn node_kind_body(ui: &mut egui::Ui, kind: &mut NodeKind) -> EditorResponse {
            match kind {
                $(
                    NodeKind::$uv => {
                        ui.label("No parameters.");
                        EditorResponse::NONE
                    }
                )*
                // Dispatched by config type through the private
                // `NodeConfigEditor` trait, which `impl_node_editor!`
                // implements for each config — the roster names types, not
                // function names.
                $( NodeKind::$dv(config) => config.edit(ui), )*
                // A patch written by a newer version of `symbios-audio`
                // decodes its unrecognised nodes here. There is nothing to
                // edit and nothing this build could safely write back
                // (`NodeKind::Unknown` is `skip_serializing` upstream), so
                // say so rather than showing an empty panel.
                NodeKind::Unknown => {
                    ui.label("This node was made by a newer version. It cannot be edited here, and saving this patch will be refused rather than overwrite it.");
                    EditorResponse::NONE
                }
                // `NodeKind` is `#[non_exhaustive]`, so the compiler keeps
                // this arm however complete the roster is.
                _ => {
                    ui.label("No editor for this node kind.");
                    EditorResponse::NONE
                }
            }
        }
    };
}

symbios_audio::for_each_node_kind!(define_kind_picker);

/// What a node kind is *for*, as the canvas's Add menu gathers them
/// (#61, Overlands #1334 B6).
///
/// A flat list of eighteen kinds asks the reader to know the vocabulary
/// before they can look anything up in it. These are the headings that list
/// is broken under.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub(crate) enum KindGroup {
    Sources,
    Envelopes,
    Filters,
    Modulators,
    Mix,
    Effects,
    /// A kind this build has no role for. See [`kind_group`].
    Other,
}

impl KindGroup {
    /// The groups in menu order: what makes sound, what shapes it over
    /// time, what colours it, what moves it, what combines it, what is done
    /// to it afterwards — and whatever is left.
    pub(crate) const ALL: [KindGroup; 7] = [
        Self::Sources,
        Self::Envelopes,
        Self::Filters,
        Self::Modulators,
        Self::Mix,
        Self::Effects,
        Self::Other,
    ];

    /// The heading the menu writes over the group.
    pub(crate) fn title(self) -> &'static str {
        match self {
            Self::Sources => "Sources",
            Self::Envelopes => "Envelopes",
            Self::Filters => "Filters",
            Self::Modulators => "Modulators",
            Self::Mix => "Mix",
            Self::Effects => "Effects",
            Self::Other => "Other",
        }
    }
}

/// The group `label` belongs under.
///
/// This is the *only* hand-written thing about the menu, and it is a hint,
/// not a roster: the menu itself is built by walking [`KIND_LABELS`], which
/// is generated from upstream's node vocabulary. A kind added to
/// `symbios-audio` therefore appears in the menu on the version bump alone,
/// under [`KindGroup::Other`] until this build is told what it is for — where
/// a hand-written menu would simply not have it, and the tests that compared
/// one hand list against another could not notice (#50).
pub(crate) fn kind_group(label: &str) -> KindGroup {
    match label {
        "Sine" | "Square" | "Sawtooth" | "Triangle" | "White Noise" | "Pink Noise"
        | "Brown Noise" | "Silence" => KindGroup::Sources,
        "ADSR" => KindGroup::Envelopes,
        "Lowpass" | "Highpass" | "Bandpass" => KindGroup::Filters,
        "LFO" => KindGroup::Modulators,
        "Mix" | "Gain" | "Gate" => KindGroup::Mix,
        "Chorus" | "Reverb" => KindGroup::Effects,
        _ => KindGroup::Other,
    }
}

/// Every kind the picker offers, gathered under its group: the groups in
/// [`KindGroup::ALL`] order, the kinds within one in the roster's order, and
/// a group no kind falls in left out.
pub(crate) fn kinds_by_group() -> Vec<(KindGroup, Vec<&'static str>)> {
    KindGroup::ALL
        .into_iter()
        .filter_map(|group| {
            let kinds: Vec<&'static str> = KIND_LABELS
                .iter()
                .copied()
                .filter(|label| kind_group(label) == group)
                .collect();
            (!kinds.is_empty()).then_some((group, kinds))
        })
        .collect()
}

/// Human-readable label for a node kind — used by the kind picker and by
/// canvas node-box headers.
///
/// Delegates to `symbios-audio`'s own `NodeKind::label`, which is generated
/// from the same roster the picker is, so there is exactly one table of node
/// names in the family rather than one per crate.
pub fn node_kind_label(kind: &NodeKind) -> &'static str {
    kind.label()
}

/// The kind picker alone: a combo whose selected text is the kind's name,
/// with no caption of its own.
///
/// This is a node box's title on the canvas — the name *is* the title, and
/// changing the kind is done where the name is written (#59, Overlands
/// #1332 B5). The box used to carry both a title reading "#0 Sawtooth" and
/// a captioned "Kind" combo under it reading "Sawtooth" again, which spent
/// a third of the box's height saying one word twice.
///
/// `id` scopes the combo's widget ids, as for [`node_kind_editor`].
pub fn node_kind_picker(ui: &mut egui::Ui, kind: &mut NodeKind, id: egui::Id) -> EditorResponse {
    let mut res = EditorResponse::NONE;
    egui::ComboBox::from_id_salt(id)
        .selected_text(node_kind_label(kind))
        .show_ui(ui, |ui| {
            for label in KIND_LABELS.iter().copied() {
                let selected = node_kind_label(kind) == label;
                if ui.selectable_label(selected, label).clicked() && !selected {
                    *kind = default_kind_for(label);
                    res.changed = true;
                    res.rebake = true;
                }
            }
        });
    res
}

/// Full editor for one [`NodeKind`]: a kind-picker combo box plus the selected
/// variant's parameter widgets.
///
/// `id` scopes egui widget ids so multiple node editors can live in one `Ui`
/// (e.g. an inspector list, or the Phase-2 graph canvas) without colliding.
/// Picking a new kind from the dropdown replaces the node with that kind's
/// `Default`, which counts as both a change and a commit.
pub fn node_kind_editor(ui: &mut egui::Ui, kind: &mut NodeKind, id: egui::Id) -> EditorResponse {
    let mut res = EditorResponse::NONE;
    ui.push_id(id, |ui| {
        egui::ComboBox::from_label("Kind")
            .selected_text(node_kind_label(kind))
            .show_ui(ui, |ui| {
                for label in KIND_LABELS.iter().copied() {
                    let selected = node_kind_label(kind) == label;
                    if ui.selectable_label(selected, label).clicked() && !selected {
                        *kind = default_kind_for(label);
                        res.changed = true;
                        res.rebake = true;
                    }
                }
            });
        res.merge(node_kind_body(ui, kind));
    });
    res
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::ui::test_paint::shapes;

    /// One frame of `kind`'s body on a headless context: what it reported
    /// and what it drew.
    ///
    /// The frame is *rendered* — B11's failure is a write that happens
    /// while the widget is drawn, with nothing touching it — so a test that
    /// only constructs the editor would see nothing.
    fn run_body(kind: &mut NodeKind) -> (EditorResponse, egui::FullOutput) {
        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        let mut res = EditorResponse::NONE;
        let out = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(600.0, 600.0),
                )),
                ..Default::default()
            },
            |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    res = node_kind_body(ui, kind);
                });
            },
        );
        (res, out)
    }

    /// A node holding `value` in one field, the field's name, and how to
    /// read it back — one row per range #1336 B11 names.
    ///
    /// One row: what it is called, the node holding it, how to read the
    /// field back, and the value it should still be afterwards.
    type OutOfTrack = (&'static str, NodeKind, fn(&NodeKind) -> f32, f32);

    /// Each value is one the *record* is allowed to hold and the editor's
    /// slider is not: the editor's ranges are the genetics bounds and the
    /// sanitiser's are wider (amplitude to ±8 against a 0-1 track, cutoff to
    /// 22 050 Hz against 20-20 000, the ADSR stages to 60 s against 10, Q to
    /// 64 against 20, an LFO to 1 000 Hz against 0.01-30).
    fn out_of_track_nodes() -> Vec<OutOfTrack> {
        vec![
            (
                "amplitude",
                NodeKind::Sine(SineOsc {
                    amplitude: 2.5,
                    ..SineOsc::default()
                }),
                (|k| match k {
                    NodeKind::Sine(c) => c.amplitude,
                    _ => unreachable!(),
                }) as fn(&NodeKind) -> f32,
                2.5,
            ),
            (
                "cutoff",
                NodeKind::BiquadLowpass(BiquadLowpass {
                    cutoff_hz: 22_000.0,
                    ..BiquadLowpass::default()
                }),
                |k| match k {
                    NodeKind::BiquadLowpass(c) => c.cutoff_hz,
                    _ => unreachable!(),
                },
                22_000.0,
            ),
            (
                "Q",
                NodeKind::BiquadLowpass(BiquadLowpass {
                    q: 64.0,
                    ..BiquadLowpass::default()
                }),
                |k| match k {
                    NodeKind::BiquadLowpass(c) => c.q,
                    _ => unreachable!(),
                },
                64.0,
            ),
            (
                "an ADSR stage",
                NodeKind::Adsr(AdsrEnvelope {
                    attack_s: 60.0,
                    ..AdsrEnvelope::default()
                }),
                |k| match k {
                    NodeKind::Adsr(c) => c.attack_s,
                    _ => unreachable!(),
                },
                60.0,
            ),
            (
                "an LFO rate",
                NodeKind::Lfo(Lfo {
                    rate_hz: 1_000.0,
                    ..Lfo::default()
                }),
                |k| match k {
                    NodeKind::Lfo(c) => c.rate_hz,
                    _ => unreachable!(),
                },
                1_000.0,
            ),
        ]
    }

    /// **B11's acceptance** (#63, Overlands #1336). A value the record is
    /// allowed to hold and the slider's track is not survives a rendered
    /// frame, bit for bit, and the frame reports nothing changed.
    ///
    /// egui's default is `SliderClamping::Always`, which writes the clamped
    /// value back on the frame the slider is *drawn*: opening a patch with
    /// an amplitude of 2.5 made it 1.0, with no `changed` flag to say so,
    /// and the pop-out's next commit wrote the loss into the record. Flip
    /// `ranged_slider`'s clamping back to `Always` and every row here fails.
    #[test]
    fn a_value_beyond_a_sliders_track_survives_being_drawn() {
        for (what, mut kind, read, value) in out_of_track_nodes() {
            let (res, _) = run_body(&mut kind);
            assert_eq!(
                read(&kind).to_bits(),
                value.to_bits(),
                "{what} was rewritten by drawing it: {} instead of {value}",
                read(&kind)
            );
            assert_eq!(
                res,
                EditorResponse::NONE,
                "{what} reported an edit nobody made"
            );
        }
        // Ten more frames: a rewrite that needs the widget to have been
        // drawn once would be invisible to a single-frame check.
        for (what, mut kind, read, value) in out_of_track_nodes() {
            for _ in 0..10 {
                run_body(&mut kind);
            }
            assert_eq!(
                read(&kind).to_bits(),
                value.to_bits(),
                "{what} drifted over ten frames"
            );
        }
    }

    /// The handle of a slider whose value is off its track is pinned at the
    /// end, which is indistinguishable from a value that really is at the
    /// end — so the row says so, and the hover says the value and the track.
    #[test]
    fn a_value_beyond_the_track_is_marked_with_its_value_and_its_range() {
        let mut kind = NodeKind::Sine(SineOsc {
            amplitude: 2.5,
            ..SineOsc::default()
        });
        let (_, out) = run_body(&mut kind);
        let painted: Vec<String> = shapes(&out)
            .into_iter()
            .filter_map(|s| match s {
                egui::Shape::Text(t) => Some(t.galley.text().to_owned()),
                _ => None,
            })
            .collect();
        assert!(
            painted.iter().any(|t| t == "!"),
            "nothing marks the amplitude as off its track: {painted:?}"
        );
        // The mark is ASCII on purpose: the hosted glyph list is a floor
        // every host has to carry a font for (#52).
        assert!(
            painted.iter().all(|t| t.is_ascii() || !t.contains('!')),
            "the mark is not the ASCII one: {painted:?}"
        );

        let mut inside = NodeKind::Sine(SineOsc {
            amplitude: 0.5,
            ..SineOsc::default()
        });
        let (_, out) = run_body(&mut inside);
        let painted: Vec<String> = shapes(&out)
            .into_iter()
            .filter_map(|s| match s {
                egui::Shape::Text(t) => Some(t.galley.text().to_owned()),
                _ => None,
            })
            .collect();
        assert!(
            !painted.iter().any(|t| t == "!"),
            "a value inside its track is marked anyway: {painted:?}"
        );
    }

    /// Every string `body` paints for `kind`, on a headless context.
    fn painted_body(kind: &mut NodeKind) -> Vec<String> {
        let ctx = egui::Context::default();
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(600.0, 600.0),
            )),
            ..Default::default()
        };
        let out = ctx.run_ui(input, |ui| {
            egui::CentralPanel::default().show(ui, |ui| {
                node_kind_body(ui, kind);
            });
        });
        shapes(&out)
            .into_iter()
            .filter_map(|s| match s {
                egui::Shape::Text(t) => Some(t.galley.text().to_owned()),
                _ => None,
            })
            .collect()
    }

    /// B15 (#59, Overlands #1332): a Gate in a patch with no sequence
    /// behind it holds open for the whole bake, and an ADSR driven by one
    /// therefore never releases — a pluck authored in a Patch slot hums.
    /// The two bodies that depend on the gate window say so.
    #[test]
    fn the_gate_and_the_adsr_say_the_gate_is_always_open_in_a_standalone_patch() {
        for mut kind in [
            NodeKind::Gate(Gate::default()),
            NodeKind::Adsr(AdsrEnvelope::default()),
        ] {
            let name = node_kind_label(&kind);
            let painted = painted_body(&mut kind);
            assert!(
                painted
                    .iter()
                    .any(|t| t.contains("always open") && t.contains("standalone patch")),
                "{name}'s body does not say its gate is always open in a standalone \
                 patch; it paints {painted:?}"
            );
            assert!(
                painted.iter().any(|t| t.contains("notes")),
                "{name}'s body does not say a sequence's notes drive it: {painted:?}"
            );
        }
    }

    #[test]
    fn label_round_trips_through_default_kind() {
        // Every label maps to a kind whose label is itself — so the picker's
        // selected-text and the dropdown rows stay consistent.
        for label in KIND_LABELS.iter().copied() {
            let kind = default_kind_for(label);
            assert_eq!(
                node_kind_label(&kind),
                label,
                "round-trip failed for {label}"
            );
        }
    }

    #[test]
    fn unknown_label_falls_back_to_silence() {
        assert!(matches!(default_kind_for("nonsense"), NodeKind::Silence));
    }

    /// Every kind `symbios-audio` ships is offered by the picker, and the
    /// picker offers nothing else.
    ///
    /// The list this used to walk was hand-written here, so it could only
    /// ever agree with the hand-written `KIND_LABELS` beside it — both went
    /// stale together the moment a kind was added upstream, and neither test
    /// could notice. `NodeKind::defaults()` comes from the crate that
    /// defines the kinds, which is the only place the roster can be
    /// authoritative.
    #[test]
    fn the_picker_offers_exactly_the_kinds_upstream_ships() {
        let upstream = NodeKind::defaults();
        assert_eq!(
            KIND_LABELS.len(),
            upstream.len(),
            "picker and upstream roster disagree on how many kinds there are"
        );
        for kind in &upstream {
            assert!(
                KIND_LABELS.contains(&node_kind_label(kind)),
                "{} missing from KIND_LABELS",
                node_kind_label(kind)
            );
        }
        for label in KIND_LABELS.iter().copied() {
            assert!(
                upstream.iter().any(|k| node_kind_label(k) == label),
                "picker offers {label}, which upstream does not ship"
            );
        }
    }

    /// `Unknown` is a decode landing place, never an offer. Picking it would
    /// build a node this build cannot edit and cannot write back.
    #[test]
    fn the_picker_never_offers_unknown() {
        assert!(!KIND_LABELS.contains(&node_kind_label(&NodeKind::Unknown)));
        assert!(!KIND_LABELS.contains(&"Unknown"));
        // And the label for it is still the one the fallback text uses, so a
        // node box that meets one is titled rather than blank.
        assert_eq!(node_kind_label(&NodeKind::Unknown), "Unknown");
    }

    // ---- step 7b (#61, Overlands #1334 B6): the Add menu's groups -------

    /// Every kind the picker offers is offered by the Add menu too, in one
    /// group and one only. The menu is built by walking `KIND_LABELS`, so a
    /// kind added upstream arrives in it on the version bump — under
    /// `Other` until this build learns what it is for.
    #[test]
    fn every_kind_label_lands_in_exactly_one_group() {
        let grouped = kinds_by_group();
        let mut seen: Vec<&str> = Vec::new();
        for (_, labels) in &grouped {
            seen.extend(labels.iter().copied());
        }
        for label in KIND_LABELS.iter().copied() {
            assert_eq!(
                seen.iter().filter(|l| **l == label).count(),
                1,
                "{label:?} is in {} groups, not one",
                seen.iter().filter(|l| **l == label).count()
            );
        }
        assert_eq!(
            seen.len(),
            KIND_LABELS.len(),
            "the groups hold {} kinds and the roster {}",
            seen.len(),
            KIND_LABELS.len()
        );
    }

    /// The #50 lesson, held: a label this build has no role for is still
    /// offered, under `Other`. A hand-written menu would simply not have
    /// it, and a test that compared two hand lists could not notice.
    #[test]
    fn a_kind_this_build_has_no_role_for_lands_in_other() {
        assert_eq!(kind_group("Granular Cloud"), KindGroup::Other);
        assert_eq!(kind_group(""), KindGroup::Other);
    }

    /// Every group the menu shows has a heading of its own, and no two
    /// share one.
    #[test]
    fn each_group_has_its_own_heading() {
        let titles: Vec<&str> = KindGroup::ALL.iter().map(|g| g.title()).collect();
        let mut sorted = titles.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), titles.len(), "two groups share a heading");
        assert!(titles.iter().all(|t| !t.is_empty()));
    }
}
